<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> [[</span><span style="color:#D19A66;">0.0</span><span style="color:#C678DD;"> for</span><span style="color:#ABB2BF;"> _ </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> range</span><span style="color:#ABB2BF;">(fan_in)] </span><span style="color:#C678DD;">for</span><span style="color:#ABB2BF;"> _ </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> range</span><span style="color:#ABB2BF;">(fan_out)]</span></span>
